package com.bank.portal.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import lombok.*;
@Entity @Table(name="monthly_statements",uniqueConstraints=@UniqueConstraint(columnNames={"card_id","periodStart"})) @Getter @Setter @NoArgsConstructor public class MonthlyStatement extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @ManyToOne(optional=false) @JoinColumn(name="card_id") private CreditCard card; @Column(nullable=false) private LocalDate periodStart; @Column(nullable=false) private LocalDate periodEnd; private LocalDate dueDate; @Column(nullable=false) private Integer lateFeeApplied=0; @Column(nullable=false,precision=15,scale=2) private BigDecimal openingBalance; @Column(nullable=false,precision=15,scale=2) private BigDecimal purchases; @Column(nullable=false,precision=15,scale=2) private BigDecimal payments; @Column(nullable=false,precision=15,scale=2) private BigDecimal closingBalance; }
